INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein sicheres Passwort immer lang und komplex?', 2, '[{"text": "Ja", "correct": true, "because": "Länge und Vielfalt erhöhen Sicherheit"}, {"text": "Nein", "correct": false, "because": "Komplexität ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel, wenn ich Zugangsdaten schütze?', 3, '[{"text": "Vertraulichkeit", "correct": true, "because": "Verhindert unbefugten Zugriff"}, {"text": "Maximale Einfachheit", "correct": false, "because": "Gefährdet Sicherheit"}, {"text": "Manuelle Speicherung", "correct": false, "because": "Unsicher und ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Passwort sicher?', 5, '[{"text": "Länge", "correct": true, "because": "Erschwert Brute-Force-Angriffe"}, {"text": "Zeichenvielfalt", "correct": true, "because": "Erhöht Entropie"}, {"text": "Wiederholte Nutzung", "correct": false, "because": "Erhöht Risiko"}, {"text": "Einfache Wörter", "correct": false, "because": "Leicht zu erraten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Passwörter sollten regelmäßig geändert werden. b) Sie dürfen überall gleich sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) erhöht Sicherheitsrisiken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines Passworts?', 4, '[{"text": "Sicherheitsrichtlinien", "correct": false, "because": "Definieren Anforderungen"}, {"text": "Uniqueness", "correct": false, "because": "Verhindert Wiederverwendung"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Passwörter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Passwörter klartext gespeichert werden sollten?', 2, '[{"text": "Nein", "correct": true, "because": "Hashing erhöht Sicherheit"}, {"text": "Ja", "correct": false, "because": "Klartext unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren schützt Passwörter am besten?', 3, '[{"text": "Hashing mit Salt", "correct": true, "because": "Erschwert Angriffe"}, {"text": "Einfache Verschlüsselung", "correct": false, "because": "Weniger sicher"}, {"text": "Klartext-Speicherung", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen erhöhen die Passwortsicherheit?', 5, '[{"text": "Zwei-Faktor-Authentifizierung", "correct": true, "because": "Fügt Schutzschicht hinzu"}, {"text": "Regelmäßige Updates", "correct": true, "because": "Reduziert Kompromittierung"}, {"text": "Kürzere Passwörter", "correct": false, "because": "Weniger sicher"}, {"text": "Wiederholte Nutzung", "correct": false, "because": "Erhöht Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Passwörter sollten mindestens 12 Zeichen haben. b) Sie sind allein ausreichend für Sicherheit. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) braucht zusätzliche Maßnahmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein sicheres Passwort?', 4, '[{"text": "Zahlen und Symbole", "correct": false, "because": "Erhöhen Komplexität"}, {"text": "Einzigartigkeit", "correct": false, "because": "Verhindert Wiederverwendung"}, {"text": "Persönliche Daten", "correct": true, "because": "Leicht zu erraten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Passwort-Manager unsicher?', 2, '[{"text": "Nein", "correct": true, "because": "Verschlüsseln und schützen Passwörter"}, {"text": "Ja", "correct": false, "because": "Sicher bei guter Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken schützen gespeicherte Passwörter?', 4, '[{"text": "Salting", "correct": true, "because": "Verhindert Rainbow-Table-Angriffe"}, {"text": "Hashing", "correct": true, "because": "Verbirgt Originalpasswort"}, {"text": "Klartext", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Passwörter immer geändert werden müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Kompromittierung nötig"}, {"text": "Ja", "correct": false, "because": "Regelmäßigkeit nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verwaltung von Zugangsdaten?', 3, '[{"text": "Sichere Speicherung", "correct": true, "because": "Schützt vor Diebstahl"}, {"text": "Einfache Wörter", "correct": false, "because": "Unsicher"}, {"text": "Manuelle Notizen", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Passwörter sollten nicht geteilt werden. b) Sie sind unwichtig bei 2FA.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) bleibt relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge helfen bei der Passwortverwaltung?', 5, '[{"text": "Passwort-Manager", "correct": true, "because": "Speichert sicher"}, {"text": "Hash-Funktionen", "correct": true, "because": "Schützen gespeicherte Daten"}, {"text": "Texteditoren", "correct": false, "because": "Unsicher"}, {"text": "Bildbearbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Passworterstellung unwichtig?', 3, '[{"text": "Komplexität", "correct": false, "because": "Erhöht Sicherheit"}, {"text": "Länge", "correct": false, "because": "Wichtig für Schutz"}, {"text": "Lieblingsfarbe", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Passwörter ohne 2FA unsicher?', 3, '[{"text": "Ja", "correct": true, "because": "Zusätzliche Schutzschicht fehlt"}, {"text": "Nein", "correct": false, "because": "2FA erhöht Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Passwörter verschlüsselt übertragen werden sollten?', 2, '[{"text": "Ja", "correct": true, "because": "Schützt vor Abfangen"}, {"text": "Nein", "correct": false, "because": "Verschlüsselung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Passwortsicherheit?', 4, '[{"text": "Absicherung eines Servers", "correct": true, "because": "Erfordert starke Zugangsdaten"}, {"text": "Bildbearbeitung", "correct": false, "because": "Keine Zugangskontrolle"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Sicherheitsfokus"}]');
